use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200000
    let mut sieve: Vec<bool> = []
    let mut i = 0
    while i <= limit {
        sieve.push(true)
        i += 1
    }
    sieve[0] = false
    sieve[1] = false
    let mut p = 2
    while p * p <= limit {
        if sieve[p] {
            let mut m = p * p
            while m <= limit {
                sieve[m] = false
                m += p
            }
        }
        p += 1
    }
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut c = 0
    let mut last = 0 - 1
    i = 0
    while i <= limit {
        if sieve[i] {
            c += 1
            last = i
        }
        counts.push(c)
        largest.push(last)
        i += 1
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = t.parse().unwrap_or(0)
        if largest[n] < 0 {
            println("0 none")
        } else {
            println("${counts[n]} ${largest[n]}")
        }
    }
}

